#!/usr/bin/env bash
# Аудит 2026-08-20 — проверка размера тестового набора для checks.yml.
#
# Раньше это был инлайн в YAML с вкомпилированным `FLOOR=670` и подписью
# «baseline 673 на 2026-06-06». Набор с тех пор вырос до трёх с лишним тысяч,
# а порог остался прежним: из набора могло исчезнуть ~78% тестов, и джоба
# осталась бы зелёной. Односторонний порог, который обновляют вручную, тухнет
# молча — и молчит тем увереннее, чем сильнее устарел.
#
# Поэтому коридор двусторонний:
#   пол     = базовая линия - 10   ловит удаление тестов;
#   потолок = базовая линия + 300  ловит устаревание самой базовой линии и
#                                  требует обновить .github/test-baseline.txt.
# Допуск вниз маленький намеренно: осмысленных удалений бывает единицы, а
# коридор должен быть узким, иначе он снова превратится в декорацию. Допуск
# вверх — запас на нормальный рост от одного PR; когда он исчерпан, обновление
# файла и есть та ручная работа, которую двусторонний коридор делает заметной.
#
# Коды выхода: 0 — норма, 1 — проверка провалена (счёт вне коридора),
# 2 — проверку не удалось выполнить: нет файла с выводом, в выводе нет сводки
# «N pass», нет или испорчен файл базовой линии. Гейт, который не смог
# проверить, обязан закрываться, а не открываться — как в
# check-conflict-markers.sh; но закрываться он должен своим кодом, иначе
# «тестов стало мало» и «замерить не вышло» неразличимы в логе.
#
# Про размер допуска вверх. Красный потолок на всех открытых PR два дня подряд
# (27–29.08) случился не потому, что 300 мало: файл базовой линии приехал уже
# устаревшим на тысячи тестов (3134 при реальных ~6600), и никакой ширины
# коридора против этого не бывает. Лечится не допуском, а тем, что число в
# .github/test-baseline.txt снимают с настоящего прогона в тот же день. Здесь
# коридор отработал ровно как задуман: громко потребовал обновления.
#
# Usage:
#   .github/scripts/assert-test-baseline.sh <bun-output-file> [<baseline-file>]

set -euo pipefail

TOLERANCE_DOWN=10
TOLERANCE_UP=300
CANONICAL=".github/test-baseline.txt"

OUTPUT_FILE="${1:-}"
BASELINE_FILE="${2:-$(dirname "$0")/../test-baseline.txt}"

if [ -z "$OUTPUT_FILE" ]; then
  echo "::error::assert-test-baseline: не передан файл с выводом bun test." >&2
  exit 2
fi

if [ ! -f "$OUTPUT_FILE" ]; then
  # Не «проверка провалена», а «проверить не смогли»: файла с замером нет,
  # про размер набора мы не узнали ничего. Код 2 — см. шапку.
  echo "::error::assert-test-baseline: файла с выводом нет: $OUTPUT_FILE" >&2
  exit 2
fi

if [ ! -f "$BASELINE_FILE" ]; then
  echo "::error::assert-test-baseline: нет файла базовой линии: $BASELINE_FILE" >&2
  exit 2
fi

# Пустые строки и комментарии — чтобы рядом с числом можно было записать, когда
# и на каком коммите оно снято.
#
# Строки склеивать нельзя. `tr -d '\n'` из первой версии превращал файл из двух
# чисел (например, дописали новое, старое не стёрли) в одно склеенное
# `66956652`: оно проходило проверку на целое число ниже, давало пол в
# 66 миллионов и роняло гейт с сообщением «из набора пропали тесты» — то есть
# ровно тем враньём, ради борьбы с которым коридор и заводили. Испорченный
# файл базовой линии — это «не смогли проверить», код 2.
BASELINE_LINES=$(sed -e 's/#.*//' -e 's/[[:space:]]//g' "$BASELINE_FILE" | grep -v '^$' || true)
LINE_COUNT=$(printf '%s\n' "$BASELINE_LINES" | grep -c . || true)
if [ "$LINE_COUNT" != "1" ]; then
  echo "::error::assert-test-baseline: в $BASELINE_FILE ожидалась одна строка с числом, найдено строк: $LINE_COUNT." >&2
  exit 2
fi
BASELINE="$BASELINE_LINES"
if ! printf '%s' "$BASELINE" | grep -qE '^[0-9]+$'; then
  echo "::error::assert-test-baseline: в $BASELINE_FILE ожидалось целое число, а там: '$BASELINE'" >&2
  exit 2
fi

# -a обязателен. Без него шаг падал при ЗЕЛЁНЫХ тестах: вывод содержит stdout
# всех тестовых файлов, то есть произвольные байты, и grep печатал «binary file
# matches» вместо совпадения. Счётчик не должен зависеть от байтовой чистоты
# чужого stdout. tail -1 — потому что сводка идёт последней, а «N pass» тест
# может напечатать и сам.
PASS_COUNT=$(grep -aoE '[0-9]+ pass' "$OUTPUT_FILE" | grep -aoE '^[0-9]+' | tail -1 || true)

if [ -z "$PASS_COUNT" ]; then
  # Тоже «не смогли проверить»: сводки нет — значит прогон не дошёл до конца
  # (упал сам bun, оборвался раннер), а не «тестов стало мало». Полный `cat`
  # убран: он выливал в лог Actions весь stdout всех тестовых файлов ровно
  # там, где его невозможно читать. Хвоста хватает, чтобы увидеть, чем
  # прогон кончился.
  echo "::error::assert-test-baseline: в выводе bun test не нашлась сводка «N pass»." >&2
  echo "--- последние 40 строк $OUTPUT_FILE ---" >&2
  tail -40 "$OUTPUT_FILE" >&2
  exit 2
fi

FLOOR=$(( BASELINE - TOLERANCE_DOWN ))
CEILING=$(( BASELINE + TOLERANCE_UP ))
echo "Тестов прошло: $PASS_COUNT; коридор [$FLOOR; $CEILING] при базовой линии $BASELINE."

if [ "$PASS_COUNT" -lt "$FLOOR" ]; then
  echo "::error::Тестов стало $PASS_COUNT — ниже пола $FLOOR. Из набора пропали тесты; если удаление намеренное, обновите $CANONICAL." >&2
  exit 1
fi

if [ "$PASS_COUNT" -gt "$CEILING" ]; then
  echo "::error::Тестов стало $PASS_COUNT — выше потолка $CEILING, базовая линия устарела. Запишите $PASS_COUNT в $CANONICAL, иначе пол перестанет что-либо ловить." >&2
  exit 1
fi

echo "OK."
